    let distance = roundedRectDistance(
        shadow_position,
        safe_shadow_size,
        shadow_radius_x,
        shadow_radius_y,
    ).x;
    let softness = max(blur, 0.5);
    let coverage = 1.0 - smoothstep(-softness, softness, distance);
    let alpha = coverage * (1.0 - outer_coverage);

    return vec4f(shadow_color.rgb, shadow_color.a * alpha);
