    let repeat_mode = panel.image_data.y;
    let repeat_x = repeat_mode == 2.0 || repeat_mode == 3.0;
    let repeat_y = repeat_mode == 2.0 || repeat_mode == 4.0;
    var image_position_local = local_position - image_position;

